-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the earthmodel capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- earthmodel / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'earthmodel' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book earthmodel refused: earthmodel/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '67494919bd18f83d27d0315fe4c26ce7' and fields = '[{"key": "s2_mean", "tol": 0.1, "unit": "m", "label": "Mean TopB depth on the model frame", "expected": 1575.5}, {"key": "clamp_s3", "tol": 0, "unit": "count", "label": "BaseB nodes fixed by the clamp", "expected": 180}, {"key": "tka_mean", "tol": 0.05, "unit": "m", "label": "Zone A mean thickness", "expected": 36}, {"key": "tka_max", "tol": 0.05, "unit": "m", "label": "Zone A maximum thickness", "expected": 42}, {"key": "tkb_mean", "tol": 0.05, "unit": "m", "label": "Zone B mean thickness", "expected": 10.24}, {"key": "bulk_a_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk rock volume", "expected": 45}]'::jsonb then 'old'
              when md5(prompt) = 'a133e1069165a6708d13b840d1016399' and fields = '[{"key": "s2_mean", "tol": 0.1, "unit": "m", "label": "Mean TopB depth on the model frame", "expected": 1575.5}, {"key": "clamp_s3", "tol": 0, "unit": "count", "label": "BaseB nodes fixed by the clamp", "expected": 180}, {"key": "tka_mean", "tol": 0.05, "unit": "m", "label": "Zone A mean thickness", "expected": 36}, {"key": "tka_max", "tol": 0.05, "unit": "m", "label": "Zone A maximum thickness", "expected": 42}, {"key": "tkb_mean", "tol": 0.05, "unit": "m", "label": "Zone B mean thickness", "expected": 10.24}, {"key": "bulk_a_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk rock volume", "expected": 45}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'earthmodel' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book earthmodel refused: earthmodel/beginner matches neither its published form (prompt md5 67494919bd18f83d27d0315fe4c26ce7) nor its W1 form (prompt md5 a133e1069165a6708d13b840d1016399), with the fields this file was generated against';
  end if;

  -- earthmodel / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'earthmodel' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book earthmodel refused: earthmodel/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'a1ef1cac1dff894b3a0bce9598baec65' and fields = '[{"key": "w2_topa_tvdss", "tol": 0.01, "unit": "m", "label": "W2 TVDSS at the TopA pick", "expected": 1496.6634373420557}, {"key": "w1_baseb_res", "tol": 0.01, "unit": "m", "label": "W1 BaseB tie residual", "expected": 5}, {"key": "w2_topb_res", "tol": 0.01, "unit": "m", "label": "W2 TopB tie residual", "expected": 8.318351595797822}, {"key": "w3_topa_res", "tol": 0.01, "unit": "m", "label": "W3 TopA tie residual", "expected": 1}, {"key": "worst_res", "tol": 0.01, "unit": "m", "label": "Largest absolute tie residual", "expected": 45.02816332199586}, {"key": "w2_cpa_x", "tol": 0.01, "unit": "m", "label": "W2 zone-A control point x", "expected": 1610.8719179395334}]'::jsonb then 'old'
              when md5(prompt) = 'a1006c387fcd39a42c94d89a7ce96744' and fields = '[{"key": "w2_topa_tvdss", "tol": 0.01, "unit": "m", "label": "W2 TVDSS at the TopA pick", "expected": 1496.6634373420557}, {"key": "w1_baseb_res", "tol": 0.01, "unit": "m", "label": "W1 BaseB tie residual", "expected": 5}, {"key": "w2_topb_res", "tol": 0.01, "unit": "m", "label": "W2 TopB tie residual", "expected": 8.318351595797822}, {"key": "w3_topa_res", "tol": 0.01, "unit": "m", "label": "W3 TopA tie residual", "expected": 1}, {"key": "worst_res", "tol": 0.01, "unit": "m", "label": "Largest absolute tie residual", "expected": 45.02816332199586}, {"key": "w2_cpa_x", "tol": 0.01, "unit": "m", "label": "W2 zone-A control point x", "expected": 1610.8719179395334}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'earthmodel' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book earthmodel refused: earthmodel/intermediate matches neither its published form (prompt md5 a1ef1cac1dff894b3a0bce9598baec65) nor its W1 form (prompt md5 a1006c387fcd39a42c94d89a7ce96744), with the fields this file was generated against';
  end if;

  -- earthmodel / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'earthmodel' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book earthmodel refused: earthmodel/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '3072aa8bddbc113c8999c8f84204b99e' and fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb then 'old'
              when md5(prompt) = '58aebea2da84ab88697ccc64d18be8a7' and fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'earthmodel' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book earthmodel refused: earthmodel/advanced matches neither its published form (prompt md5 3072aa8bddbc113c8999c8f84204b99e) nor its W1 form (prompt md5 58aebea2da84ab88697ccc64d18be8a7), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book earthmodel: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book earthmodel refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Resample the three source surfaces (TopA, TopB, BaseB — each on its own grid) onto the 25x20 model frame at 50 m cells, apply the depth-down monotonic clamp, and derive the two zone thickness grids. Read the framework panel: the mean TopB depth, how many BaseB nodes the clamp fixed (the zone B pinch-out), zone A''s mean and maximum thickness, zone B''s mean thickness, and zone A''s bulk rock volume.',
           fields = '[{"key": "s2_mean", "tol": 0.1, "unit": "m", "label": "Mean TopB depth on the model frame", "expected": 1575.5}, {"key": "clamp_s3", "tol": 0, "unit": "count", "label": "BaseB nodes fixed by the clamp", "expected": 180}, {"key": "tka_mean", "tol": 0.05, "unit": "m", "label": "Zone A mean thickness", "expected": 36}, {"key": "tka_max", "tol": 0.05, "unit": "m", "label": "Zone A maximum thickness", "expected": 42}, {"key": "tkb_mean", "tol": 0.05, "unit": "m", "label": "Zone B mean thickness", "expected": 10.24}, {"key": "bulk_a_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk rock volume", "expected": 45}]'::jsonb
     where app_slug = 'earthmodel' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book earthmodel refused: earthmodel/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'a133e1069165a6708d13b840d1016399' and fields = '[{"key": "s2_mean", "tol": 0.1, "unit": "m", "label": "Mean TopB depth on the model frame", "expected": 1575.5}, {"key": "clamp_s3", "tol": 0, "unit": "count", "label": "BaseB nodes fixed by the clamp", "expected": 180}, {"key": "tka_mean", "tol": 0.05, "unit": "m", "label": "Zone A mean thickness", "expected": 36}, {"key": "tka_max", "tol": 0.05, "unit": "m", "label": "Zone A maximum thickness", "expected": 42}, {"key": "tkb_mean", "tol": 0.05, "unit": "m", "label": "Zone B mean thickness", "expected": 10.24}, {"key": "bulk_a_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk rock volume", "expected": 45}]'::jsonb) from public.academy_capstones where app_slug = 'earthmodel' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book earthmodel refused: earthmodel/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Build minimum-curvature trajectories for the four wells (W2 carries a real 45 degree build), land every top in 3D, and tie each against its framework surface (residual = pick TVDSS minus the surface there). Report W2''s TVDSS at its TopA pick, three residuals from the tie table (W1 BaseB, W2 TopB, W3 TopA), the largest absolute residual in the well set, and the x coordinate of W2''s zone-A control point (the zone''s MD midpoint along the path).',
           fields = '[{"key": "w2_topa_tvdss", "tol": 0.01, "unit": "m", "label": "W2 TVDSS at the TopA pick", "expected": 1496.6634373420557}, {"key": "w1_baseb_res", "tol": 0.01, "unit": "m", "label": "W1 BaseB tie residual", "expected": 5}, {"key": "w2_topb_res", "tol": 0.01, "unit": "m", "label": "W2 TopB tie residual", "expected": 8.318351595797822}, {"key": "w3_topa_res", "tol": 0.01, "unit": "m", "label": "W3 TopA tie residual", "expected": 1}, {"key": "worst_res", "tol": 0.01, "unit": "m", "label": "Largest absolute tie residual", "expected": 45.02816332199586}, {"key": "w2_cpa_x", "tol": 0.01, "unit": "m", "label": "W2 zone-A control point x", "expected": 1610.8719179395334}]'::jsonb
     where app_slug = 'earthmodel' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book earthmodel refused: earthmodel/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'a1006c387fcd39a42c94d89a7ce96744' and fields = '[{"key": "w2_topa_tvdss", "tol": 0.01, "unit": "m", "label": "W2 TVDSS at the TopA pick", "expected": 1496.6634373420557}, {"key": "w1_baseb_res", "tol": 0.01, "unit": "m", "label": "W1 BaseB tie residual", "expected": 5}, {"key": "w2_topb_res", "tol": 0.01, "unit": "m", "label": "W2 TopB tie residual", "expected": 8.318351595797822}, {"key": "w3_topa_res", "tol": 0.01, "unit": "m", "label": "W3 TopA tie residual", "expected": 1}, {"key": "worst_res", "tol": 0.01, "unit": "m", "label": "Largest absolute tie residual", "expected": 45.02816332199586}, {"key": "w2_cpa_x", "tol": 0.01, "unit": "m", "label": "W2 zone-A control point x", "expected": 1610.8719179395334}]'::jsonb) from public.academy_capstones where app_slug = 'earthmodel' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book earthmodel refused: earthmodel/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Label the model with the fault polygon and run everything per block: the block-1 node count, the plane-trend porosity at (1250, 2250), the kriged porosity at (1500, 2500), and the porosity jump across the fault on the y = 2200 row of the per-block kriged map (the block 0 node at x 1600 minus the block 1 node at x 1550, sign kept), both by simple kriging on the stated spherical variogram (sill 0.0025, nugget 0.00025, range 900 m), zone A''s interval-weighted porosity in block 0, and zone A''s bulk rock volume in block 1.',
           fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb
     where app_slug = 'earthmodel' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book earthmodel refused: earthmodel/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '58aebea2da84ab88697ccc64d18be8a7' and fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb) from public.academy_capstones where app_slug = 'earthmodel' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book earthmodel refused: earthmodel/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book earthmodel: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
